{"type":"match","data":{"path":{"text":"theonlinephotographer.typepad.com/The Online Photographer.txt"},"lines":{"text":"Humor has since been banned from art too, another sanction I think is tiresome. I digress.\n"},"line_number":19,"absolute_offset":1398,"submatches":[{"match":{"text":"banned"},"start":21,"end":27}]}}
{"type":"end","data":{"path":{"text":"theonlinephotographer.typepad.com/The Online Photographer.txt"},"binary_offset":null,"stats":{"elapsed":{"secs":0,"nanos":7588471,"human":"0.007588s"},"searches":1,"searches_with_match":1,"bytes_searched":47770,"bytes_printed":427,"matched_lines":1,"matches":1}}}
